settings.custom_liquid:
{%- comment -%}
  ### Zestaw – elegancka lista składników (z linkami)
  • Metafield: product.metafields.custom.w_zestawie  (list.product_reference / JSON)
{%- endcomment -%}

{% if product.metafields.custom.w_zestawie != blank %}
  <style>
    /* --------- STYL BUNDLE --------- */
    .bundle-contents{margin-top:2rem}
    .bundle-contents h3{font-size:1.5rem;font-weight:600;margin-bottom:1rem}

    .bundle-contents ul{
      display:flex;flex-direction:column;gap:1rem;
      list-style:none;padding:0;margin:0;
    }
    .bundle-contents li{ /* cały wiersz jest linkiem */
      /* gap zostaje w <a>, więc <li> ma zerowe wewn. marginesy */
    }

    .bundle-link{display:flex;align-items:center;gap:1rem;
                 text-decoration:none;color:inherit;}
    .bundle-link:hover .component-title{text-decoration:underline;}

    .bundle-contents img{
      width:64px;height:64px;object-fit:contain;
      border-radius:6px;box-shadow:0 1px 4px rgba(0,0,0,.06);
    }
    .component-title{font-size:1rem;line-height:1.35;}

    @media (min-width:768px){
      .bundle-contents img{width:80px;height:80px}
    }
    /* --------- /STYL BUNDLE --------- */
  </style>

  <div class="bundle-contents">
    <h3>Zestaw zawiera:</h3>
    <ul>
      {%- for ref in product.metafields.custom.w_zestawie.value -%}
        {%- assign comp = all_products[ref.handle] -%}
        <li>
          <a href="{{ comp.url | within: collection }}"
             class="bundle-link"
             title="Zobacz szczegóły: {{ comp.title | escape }}">
            <img
              src="{{ comp.featured_image | image_url: width: 160 }}"
              alt="{{ comp.title | escape }}"
              loading="lazy">
            <span class="component-title">
              {{ comp.title }}
              {%- if ref.qty %} × {{ ref.qty }}{% endif -%}
            </span>
          </a>
        </li>
      {%- endfor -%}
    </ul>
  </div>
{% endif %}
